# Komoku köşe kapatmaları: iki boşluklu kapatma (B-6-4)
T_IKIBOSLUKKAPATMA = {
'B-6-4': ("Başlangıç pozisyonu", 'best', "Eskiden iki boşluklu zıplayarak kapatmak köşeyi fazla boş bıraktığı için pek kabul görmezdi. Yapay zekâ bu bakışı değiştirdi; bugün en popüler kapatmadır. Duruma göre beyazın beş cevabı vardır: A ya da B'de yaklaşma, C'de hoshi noktasına yapışma, D ve E'de işgal."),
'B-6-4-1-1-1': ("Beyaz yaklaşır", 'best', "Beyaz 1 ile yaklaşmak çok büyüktür; siyah genelde tenuki düşünür. İleride beyazın A'da yapışması mükemmel bir noktadır."),
'B-6-4-1-1-2': ("Beyaz yapışır", 'ok', "Beyaz 1 yapışması bu şekilde sık kullanılır; siyah 2 ile dıştan hane bir yoldur, beyaz 3 ile sade şekilde aşağı iner. Siyah 6 ve 8 alana önem verir; beyaz tenuki düşünebilir, ileride siyahın A'da taş alması çok büyüktür. Sonuç eşittir."),
'B-6-4-1-1-3': ("Siyah yapışır – fazla", 'bad', "Siyah 1 yapışması fazladır; beyaz yine tenuki yapabilir. İleride beyazın A'da hane, B'de ko ve C'de kosumi gibi imkânları vardır; dört beyaz taş çok hafiftir."),
'B-6-4-1-1-4': ("Siyah kaplan ağzı", 'ok', "Siyah 1 kaplan ağzı sente almak içindir; beyaz 2 ile sakince kaplan ağzı ile kapatır. B-6-4-1-1-2 ile hangisinin daha iyi olduğunu söylemek zordur."),
'B-6-4-1-1-5': ("Siyah kosumi ile dayanır", 'situational', "İleride siyah 1 ile kosumi şeklinde dayanmak iyi hamledir; beyaz 2 ve 4 ile doğrudan karşılar. Siyah 7 ile kıvrılıp çıkmak serttir ve zor bir karşılıklı saldırı olur."),
'B-6-4-1-1-6': ("Siyah hane ile köşeyi alır – uygun değil", 'bad', "Siyah 1 ile hane yapıp köşeyi almak uygun değildir; beyaz 6 ve 8 ile sente rahatça kapatır, beyaz açıkça önde."),
'B-6-4-1-1-7': ("Beyaz hane yapıp geçer – yumuşak", 'bad', "Beyaz 1 ile hane yapıp geçmek biraz yumuşaktır; siyah 2 ile sente kaplan ağzı yapmak çok rahattır."),
'B-6-4-1-1-8': ("Siyah alttan yapışır", 'ok', "Siyah 1 ile alttan yapışmak sade bir yoldur; siyah 3'ten itibaren birkaç değiş tokuştan sonra beyazın A'dan hane yapıp çıkma imkânını sente ile önler."),
'B-6-4-1-1-9': ("Siyah keima ile vurur – fazla", 'bad', "Siyah 1 ile keima şeklinde vurmak fazladır; beyaz 4 ile keima arasına girmek keskindir, siyah 5 ile araya girmek en güçlü direniştir. Beyaz 8'den itibaren doğru sırayla oynar; siyah 15 ile mecburen değiş tokuş eder, alan kaybı çok büyüktür."),
'B-6-4-1-1-10': ("Beyaz içeriden hane", 'situational', "Merdiven iyiyken beyaz 1 ile içeriden hane işler; siyah 2 bağlanması güçlüdür, beyaz 5 ve 7 ile sade şekilde geçer. Sonuç eşittir."),
'B-6-4-1-1-11': ("Beyaz hane ile çıkar", 'ok', "Beyaz 1 ile hane yapıp çıkmak taş feda edip merkez kurmak içindir. Siyah 4 ile nefes azaltınca beyaz 5 ile sıkıca döner, sonra 9 ile zıplayıp kapatmak tutarlı bir fikirdir. Siyah 10'dan itibaren beyazın köşesini tamamen alır; iki taraf da kabul edebilir."),
'B-6-4-1-1-12': ("Siyah itip keser – karışık", 'situational', "Önceki diyagramda siyah 10 yerine 1'de itip kesmek çok karışıktır; beyaz 4 kesmesi zamanında gelir, siyah 5'ten itibaren karşılık vermek zorundadır. Siyah 19 ve 21 doğru sıradır, beyaz 22 ile sürünüp kararlıca değiş tokuş eder; sonucu kestirmek zordur."),
'B-6-4-1-1-13': ("Beyaz bağlanıp çıkar", 'situational', "Çevrede destek varsa önceki diyagramda beyaz 22 yerine 1'de bağlanıp çıkabilir; siyah 6 ile yapışıp çıkar ve karışık bir savaş olur."),
'B-6-4-1-1-14': ("Beyaz keima – gevşek", 'bad', "Beyaz 1 keimasi yeterince sıkı değildir; siyah 2 ile nefes azaltıp köşeyi alarak memnun kalır."),
'B-6-4-1-1-15': ("Siyah yapışır – merkez için", 'bad', "Siyah 1 yapışması merkez içindir; beyaz 6 ile alttan yapışıp geçmek kârlıdır, siyah yerel olarak biraz kayıptır."),
'B-6-4-1-1-16': ("Siyah kosumi ile dayanır – fazla", 'bad', "Siyah 1 ile kosumi şeklinde dayanmak biraz fazladır; beyaz 2 ile hane yapıp çıkmak serttir, siyah 3 ile sakince yön değiştirmesi iyidir. Beyaz 4 ile keima ile iner, siyah 5 hanesi en güçlüsüdür. Beyaz iki taraftan kazanıp 16 ile yaklaşma noktasını alır; beyaz biraz daha etkindir."),
'B-6-4-1-1-17': ("Siyah keserse", 'bad', "Siyah 1 ile keserse beyaz 2 ve 4 ile mükemmel şekilde kapatır. Siyah 5 ile itip keserek imkân arar, beyaz 10'dan itibaren doğru sırayla oynar; siyah 15 ile köşeyi almak zorunda kalır, beyaz 16 ile başa vurmak rahattır; siyah sıkışır."),
'B-6-4-1-1-18': ("Siyah uzayıp çıkar – düşüncesiz", 'bad', "Siyah 1 ile düşüncesizce uzayıp çıkarsa beyaz 2 ve 4 sente değiş tokuşlarından sonra 8 ile uzayıp çıkmak çok serttir; siyah savaşta açıkça geride."),
'B-6-4-1-1-19': ("Beyaz dayanıp geçer – kaba", 'ok', "Beyaz 1 ile dayanıp geçmek sade ama kabadır; beyaz B-6-4-1-1-10'dan biraz kötüdür."),
'B-6-4-1-1-20': ("Siyah ters kaplan ağzı", 'ok', "Siyah 1 ters kaplan ağzı da bir yoldur; beyaz 4 ile köşeye hane gerekli bir değiş tokuştur, sonra beyaz 6 ve 8 ile alttan yapışıp geri bağlanır. Sonuç eşittir."),
'B-6-4-1-1-21': ("Siyah sadece uzar", 'ok', "Siyah 1 ile sadece uzamak da olur; beyaz 2 atarisi sağlamdır, iki taraf da oynanabilir."),
'B-6-4-1-1-22': ("Beyaz alttan yapışıp geçer", 'situational', "Merdiven iyiyken beyaz 1 ile alttan yapışıp geçmek güçlüdür; siyah 2 ile araya girmek en güçlü cevaptır. Beyaz 7 hanesinde siyah 8 ile önce kesmelidir; iki taraf uzlaşır, sonuç eşittir."),
'B-6-4-1-1-23': ("Beyaz hane ile çıkar – fazla", 'bad', "Beyaz 1 ile hane yapıp çıkmak biraz fazladır; siyah 6 ile önce kosumi iyi sıradır, sonra siyah 10 ile sertçe yapışır; beyaz savaşta biraz zorlanır."),
'B-6-4-1-1-24': ("Beyaz doğrudan alttan yapışır – yumuşak", 'bad', "Beyaz 1 ile doğrudan alttan yapışmak biraz yumuşaktır; siyah 2 ile dayanınca beyaz 3 ile içeride bağlanmak zorunda kalır, B-6-4-1-1-20'den biraz kötüdür."),
'B-6-4-1-1-25': ("Siyah keserek atari", 'bad', "Siyah 1 ile keserek atari sadelik arar; beyaz 6 ile önce dönmek iyi hamledir, sonra beyaz 8 kesmesi keskindir. Siyah 9 ve 11 ile sabretmek zorunda kalır, beyaz 12 ile ağ kurup iki taşı alarak memnun kalır."),
'B-6-4-1-1-26': ("Siyah başa döner – cesur", 'bad', "Siyah 1 ile başa dönmek bir anlık cesarettir; beyaz 2 ve 4 doğru sıradadır, sonra beyaz 8 ile başa kaplan ağzı güçlüdür. Siyah tek taraflı kaçmak zorunda kalır; beyaz çok etkindir."),
'B-6-4-1-1-27': ("Beyaz aşağı iner – fazla", 'ok', "Beyaz 1 ile aşağı inmek fazla güçlüdür; siyah 2 ile önce atari yapmalıdır, sonra 4 ile bastırıp çıkınca karışık bir savaş olur."),
'B-6-4-1-1-28': ("Siyah alttan hane", 'ok', "Siyah 1 ile alttan hane de olur; beyaz 2 çift hanesi doğaldır, sonra beyaz 6 ve 8 ile sağ tarafı geliştirmeye döner. Siyah 9 zıplaması şekildir, beyaz 10 ve 12 ile artık taşların imkânlarını iyi kullanır; sonuç eşittir."),
'B-6-4-1-1-29': ("Siyah sadece dayanır", 'ok', "Siyah 1 ile sadece dayanmak hemen hemen aynıdır; beyaz 2 zıplayınca önceki diyagrama döner."),
'B-6-4-1-1-30': ("Beyaz döner – tuzağa düşer", 'bad', "Beyaz 1 ile dönmek tuzağa düşmektir; siyah 2 ağı beyazı kıpırdatmaz. Beyaz 3 ile ısrarla hareket ederse siyah 4 ve 6 ile iterek keser; beyaz 7 ile mecburen değiş tokuş eder, siyah çok alan kazanır."),
'B-6-4-1-1-31': ("Beyaz bağlanır – ağır", 'bad', "Beyaz 1 ile bağlanmak biraz ağırdır; siyah 2 ile sıkıca burna dayanır, beyaz 3 ile önce dönmek incedir. Beyaz 7 ile dönüp çıkınca siyah 8 ve 10 ile mükemmel şekilde taş feda eder ve geniş bir merkez kurar."),
'B-6-4-1-1-32': ("Siyah zıplayıp çıkar", 'ok', "Önceki diyagramda siyah 8 yerine 1'de zıplayıp çıkarak savaşabilir; beyaz 4 hanesi ustaca sıradır, savaş dengelidir."),
'B-6-4-1-1-33': ("Beyaz doğrudan döner – özensiz", 'bad', "Beyaz 1 ile doğrudan dönüp çıkmak yeterince ince değildir; siyah 4 çift hanesi güçlüdür, siyahın şekli B-6-4-1-1-31'dekinden açıkça daha dolgundur."),
'B-6-4-1-1-34': ("Beyaz sert aşağı iner", 'situational', "Beyaz 1 ile aşağı inmek serttir; siyah 2 keimasi kilit noktadır, beyaz 3 zıplayıp savaşır. Savaşın sonucu çevredeki taşlara bağlıdır."),
'B-6-4-1-1-35': ("Siyah 3-3'e uzar – yumuşak", 'bad', "Siyah 1 ile 3-3'e uzamak biraz yumuşaktır; beyaz 2 ile zıplayıp sente kazanır."),
'B-6-4-1-2-1': ("Siyah karşı pincer", 'situational', "Sağ alt destekliyse siyah 1 karşı pinceri işler; beyaz 2 ile sağlamca zıplar. Siyah 3 zıplayıp büyür, beyaz 4 ile köşeye yapışıp destek arar, siyah 5 ve 7 ile sakince korur; iki taraf da oynanabilir."),
'B-6-4-1-2-2': ("Siyah kosumi ile dayanır – şüpheli", 'bad', "Siyah 1 ile kosumi şeklinde dayanmak biraz şüphelidir; beyaz 2 ile önce hane yapar, sonra 4 ile keskin şekilde yapışır. Siyah 5'ten itibaren köşeyi korur ama şekli biraz tekrar eder."),
'B-6-4-1-2-3': ("Siyah alttan hane", 'bad', "Siyah 1 ile alttan hane yaparsa beyaz 2 ile sadece uzamak iyi hamledir, sonra 4 ve 6 ile iyi şekil kurar; siyah önceki diyagramdan da kötüdür."),
'B-6-4-1-3-1': ("Siyah omuz vuruşu – fazla", 'bad', "Siyah 1 omuz vuruşu fazla güç kullanır; beyaz 2 ve 4 ile itip keserek karşılık verir, sonra beyaz 6 yapışması çok rahatsız edicidir. Siyah 7'den itibaren inatla savunur, beyaz 16'dan itibaren sade şekilde taş feda edip 22 ve 24 ile iyi noktaları alır; beyaz memnundur."),
'B-6-4-2-1-1': ("Beyaz bu taraftan yaklaşır", 'best', "Beyazın solda taşı varsa beyaz 1 ile bu taraftan yaklaşmak da çok yaygındır; siyahın tenuki yapması iyidir. İleride merdiven beyazın lehine olursa A'da yapışma iyi devam noktasıdır."),
'B-6-4-2-1-2': ("Beyaz yapışır", 'ok', "Beyaz 1 yapışması iyi hamledir; siyah 2 ile sakince 3-3'e uzar, beyaz 3 ile kosumi yapıp geri dönerek sente kalınlaşır. İki taraf da kabul edebilir."),
'B-6-4-2-1-3': ("Siyah dıştan hane", 'ok', "Siyah 1 ile dıştan hane serttir; beyaz 2 ile siyah 3 karşı karşıya gelir, beyaz 4 ve 6 ile atari yapıp çıkarak değiş tokuş eder; sonuç eşittir."),
'B-6-4-2-1-4': ("Siyah ters kaplan ağzı", 'bad', "Siyah 1 ters kaplan ağzı yaparsa beyaz 2 ile hane yapıp taş feda etmek güçlüdür; siyah B-6-4-2-1-2'den biraz kötüdür."),
'B-6-4-2-1-5': ("Siyah atari – şüpheli", 'bad', "Siyah 1 atarisi şüphelidir; beyaz 6 ile aşağı inmek iyi hamledir ve taş feda ederek iki taraftan kazanır. Beyaz 22 ile önce yapışmak incedir, siyah 27 ile gote kapatmak zorunda kalır; beyaz açıkça kazanır."),
'B-6-4-2-1-6': ("Siyah içeriden hane", 'bad', "Siyah 1 ile içeriden hane yaparsa beyaz 2 ile bükerek kesmek iyi hamledir; siyah 3 ve 5 ile mecburen köşeyi alır, beyaz sente şekli bitirip memnun kalır."),
'B-6-4-2-1-7': ("Siyah atari – kötü", 'bad', "Siyah 1 atarisi iyi değildir; B-6-4-2-1-5 diyagramına döner."),
'B-6-4-3-1-1': ("Hoshi noktasına yapışma – uygun değil", 'bad', "Çevrede destek yoksa beyaz 1 ile doğrudan hoshi noktasına yapışmak uygun değildir; siyah 2 ile alttan hane güçlüdür, sonra 4 ile sadece geri çekilmesi yeterlidir. Beyaz tenuki yapıp kaybı durdurmak zorunda kalır."),
'B-6-4-3-1-2': ("Beyaz doğrudan yaşar – kayıp", 'bad', "Beyaz 1 ile doğrudan köşede yaşamak kaybettirir; siyah 6 ile dönmek hem kalın hem büyüktür."),
'B-6-4-3-1-3': ("Atari sonra kaplan ağzı – daha kötü", 'bad', "Beyaz 1 ve 3 ile atari yapıp kaplan ağzı kurmak daha da kötüdür; siyah 4 ile önce işgal ederek tempo alır, beyazın şekli çok ağırlaşır."),
'B-6-4-3-2-1': ("Siyah üstten hane", 'ok', "Merdiven iyi olsa bile siyah 1 ile üstten hane genelde 2'de alttan haneden zayıftır; beyaz 2 ile aşağı inince yerel olarak birçok imkân doğar. Siyah 5 ve 7 güçlüdür, beyaz 8 ve 10 ile esnekçe yön değiştirir; sonuç eşittir."),
'B-6-4-3-2-2': ("Beyaz çift hane", 'situational', "Merdiven iyiyken beyaz 1 ile çift hane yapabilir; siyah 2 ters kaplan ağzı ile sakin kalır. Beyaz 3 ile bir kez bağlanıp tenuki yapması iyidir; yine eşit bir varyasyondur."),
'B-6-4-3-2-3': ("Siyah keserek atari – kötü", 'bad', "Çevrede destek yoksa siyah 1 ile keserek atari genelde iyi değildir; beyaz 6 kesmesi güçlüdür. Siyah 9 ile sağlamca sürünür, beyaz 14 ile başa dönmek çok güçlüdür; beyaz memnundur."),
'B-6-4-3-2-4': ("Siyah bastırıp çıkar", 'bad', "Önceki diyagramda siyah 9 yerine 1'de bastırıp çıkarsa beyaz 2 ile sertçe döner. Siyah 9 ile bastırınca beyaz 10 ile başa vurup karşılık verir; savaşta beyaz biraz daha etkindir."),
'B-6-4-3-2-5': ("Sağ alt beyazken", 'situational', "Sağ alt beyazsa beyaz 1 ve 3 ile atari yapıp kaçmak da olur; siyah 4 ile başa dönünce beyaz 5'ten itibaren sakince taş feda edip memnun kalır. Ama sağ alt siyahsa bu diyagram beyaz için kötüdür."),
'B-6-4-3-2-6': ("Beyaz taş feda etmek istemez", 'bad', "Beyaz 1 ile taş feda etmek istemezse siyah 2 ile başa vurmak çok büyüktür; iki taraf kendi yolunda gider, beyaz önceki diyagram kadar iyi değildir."),
'B-6-4-4-1-1': ("Beyaz işgal eder", 'bad', "Beyaz 1 işgali genelde siyahın sağ taraftaki alanını küçültmek için kullanılır; doğrudan oynamak biraz kayıptır. Siyah 2 ile kalınca bastırır, beyaz 3 ile alttan yapışmak iyi hamledir. Siyah 4 ve 6 ile araya girip bağlanarak köşeyi alır, beyaz 7 ve 9 ile başarıyla yön değiştirir."),
'B-6-4-4-1-2': ("Siyah atari – kayıp", 'bad', "Siyah 1 atarisi kaybettirir; beyaz 4 ters atarisinden sonra şekli daha esnek olur."),
'B-6-4-4-1-3': ("Siyah dıştan hane ile kapatır", 'ok', "Siyah 1 ile dıştan hane yapıp kapatmak da olur; beyaz 2'den itibaren yerinde yaşayabilir."),
'B-6-4-4-2-1': ("Siyah köşeyi engeller – kazanç verir", 'bad', "Siyah 1 ile köşeyi engellemek beyaza kazanç verir; ileride beyaz duruma göre A–C imkânlarını kullanabilir."),
'B-6-4-5-1-1': ("Beyaz bu taraftan işgal – kötü", 'bad', "Beyaz 1 ile bu taraftan işgal etmek genelde iyi değildir; siyah 2 ile bastırmak çok kalındır. Beyaz 3 ile alttan yapışıp zorla yaşamak zorunda kalır, çok sıkışır."),
'B-6-4-5-2-1': ("Siyah dıştan engeller – zayıf", 'bad', "Siyah 1 ile dıştan engellemek biraz zayıftır; beyaz 2 ile önce itmek gereklidir. Beyaz 8 ile köşeye zıplayınca siyah 9 ile kapatmak zorundadır, beyaz 10 rahat bir sente kazancıdır; siyah önceki diyagramdan açıkça kötüdür."),
'B-6-4-5-2-2': ("Siyah dayanır", 'bad', "Önceki diyagramda siyah 5 yerine 1'de dayanırsa beyaz 2 kaplan ağzı şekildir, sonra 4 ve 6 ile kolayca yaşar; siyahın saldırısı başarısız olur."),
}
